(() => {
'use strict';
const D=window.MISSION_DATA, KEY='dz-traumschiff-v1';
const fresh=()=>({version:1,unlocked:[],answers:{},notes:{},checks:[],basis:{},route:'start'});
let state=fresh(), storageOK=true;
try {const s=JSON.parse(localStorage.getItem(KEY));if(s&&s.version===1){state={...fresh(),...s,unlocked:Array.isArray(s.unlocked)?s.unlocked.filter(x=>D.some(d=>d.id===x)):[],answers:s.answers&&typeof s.answers==='object'?s.answers:{},notes:s.notes&&typeof s.notes==='object'?s.notes:{},checks:Array.isArray(s.checks)?s.checks:[],basis:s.basis&&typeof s.basis==='object'?s.basis:{}};}} catch {storageOK=false;}
const main=document.querySelector('#main'), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const routes=[['start','An Bord','Einstieg'],['basis','Kompass','Grundlagen'],...D.map(s=>[s.id,s.title,s.dimension]),['bruecke','Brücke','Abschlussmission']];
const allowed=['start','werbung','basis',...D.map(s=>s.id),'bruecke','diskussion','quellen','ergebnis'];
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;}document.querySelector('#storage').textContent=storageOK?'Euer Fortschritt bleibt auf diesem Gerät. Keine Namen nötig.':'Speichern ist hier nicht möglich. Lasst diese Seite offen und druckt euer Logbuch vor dem Schließen.';};
function note(id,label,placeholder=''){return `<label class="field"><span>${label}</span><textarea data-note="${id}" maxlength="5000" placeholder="${placeholder}">${esc(state.notes[id])}</textarea></label>`;}
const rooms={umwelt:{deck:'Deck 01',zone:'Maschinenraum',icon:'engine'},wirtschaft:{deck:'Deck 04',zone:'Reedereibüro',icon:'file'},soziales:{deck:'Deck 02',zone:'Crewbereich',icon:'crew'},bruecke:{deck:'Deck 07',zone:'Kommandobrücke',icon:'compass'}};
function icon(name){const paths={engine:'<path d="M4 10h15v10H4zM8 6h7v4M19 13h3v5h-3M1 12h3M1 18h3M8 14h7"/>',file:'<path d="M6 3h8l4 4v14H6zM14 3v5h4M9 12h6M9 16h6"/>',crew:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 4a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 5v2"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6zM12 1v2M12 21v2M1 12h2M21 12h2"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',check:'<path d="m5 12 4 4L19 6"/>',wave:'<path d="M2 9q3-4 6 0t6 0t6 0M2 16q3-4 6 0t6 0t6 0"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.compass}</svg>`;}
function head(k,t,p){const id=route(),r=rooms[id];return `<header class="scene-heading scene-${id}"><div class="scene-copy"><div class="kicker">${icon(r?.icon||'compass')}${k}</div><h1>${t}</h1>${p?`<p>${p}</p>`:''}</div><div class="room-plaque" aria-hidden="true">${r?r.deck:'MS Morgenwind'}<strong>${r?r.zone:id==='basis'?'Bordbriefing':'An Bord'}</strong></div></header>`;}
function doorStatus(id){const i=D.findIndex(s=>s.id===id);return state.unlocked.includes(id)?'Akte geöffnet':i>0&&!state.unlocked.includes(D[i-1].id)?'Noch gesperrt':id==='bruecke'?'Euer Urteil':'Jetzt zugänglich';}
function deckDoors(){return `<section class="deck-journey" aria-labelledby="deck-heading"><div class="section-top"><div><h2 id="deck-heading">Euer Weg durch das Schiff</h2><p>Drei Bordakten. Eine gemeinsame Entscheidung.</p></div><span>${state.unlocked.length} / 3 Akten</span></div><div class="cabin-row">${Object.entries(rooms).map(([id,r],i)=>`<a class="cabin-door ${state.unlocked.includes(id)?'complete':''} ${doorStatus(id)==='Noch gesperrt'?'locked':''}" href="#${id}" aria-label="${r.zone}: ${doorStatus(id)}"><div class="cabin-top"><span>${r.deck}</span>${icon(state.unlocked.includes(id)?'check':doorStatus(id)==='Noch gesperrt'?'lock':r.icon)}</div><div class="porthole" aria-hidden="true"><div class="porthole-view view-${id}"></div></div><strong>${r.zone}</strong><span class="cabin-state">${doorStatus(id)}</span><span class="cabin-handle" aria-hidden="true"></span></a>`).join('')}</div></section>`;}
function compass(){return `<div class="compass-chart" role="img" aria-label="Nachhaltigkeitskompass: Umwelt, Wirtschaft und Soziales müssen gemeinsam betrachtet werden."><svg viewBox="0 0 440 390" aria-hidden="true"><circle class="ring" cx="220" cy="190" r="150"/><circle class="ring inner" cx="220" cy="190" r="130"/><path class="cross" d="M220 22v336M52 190h336"/><path class="triangle" d="M220 60 92 264 348 264Z"/><path class="needle" d="M220 100 237 190 220 235 203 190Z"/><circle class="hub" cx="220" cy="190" r="9"/><text x="220" y="41" text-anchor="middle">UMWELT</text><text x="82" y="302" text-anchor="middle">WIRTSCHAFT</text><text x="355" y="302" text-anchor="middle">SOZIALES</text><text class="chart-caption" x="220" y="365" text-anchor="middle">Drei Perspektiven. Ein gemeinsamer Kurs.</text></svg></div>`;}
function link(id,text,primary=true){return `<a class="button ${primary?'primary':''}" href="#${id}">${text}</a>`;}
function route(){let id=location.hash.slice(1)||state.route;if(!allowed.includes(id))id='start';return id;}
function nav(){const id=route();document.querySelector('#route').innerHTML=routes.map(([r,t,sub],i)=>`<a class="route-link" href="#${r}" ${id===r?'aria-current="page"':''}><span class="route-num" aria-hidden="true">${state.unlocked.includes(r)?'✓':i<2?'·':i-1}</span><span>${t}<small>${state.unlocked.includes(r)?'Akte geöffnet':sub}</small></span></a>`).join('');document.querySelector('#progress').value=state.unlocked.length;document.querySelector('#progress-label').textContent=`${state.unlocked.length} von 3 Akten geöffnet`;}
function campaign(){return `<section class="campaign" aria-labelledby="campaign-title"><div class="campaign-disclosure"><span>Erfundene Werbung für den Unterricht</span><span>Keine Buchung möglich</span></div><div class="campaign-visual"><img src="assets/sonnendeck.webp" width="1536" height="1024" fetchpriority="high" alt="Inszeniertes Urlaubsmotiv: türkisblauer Pool auf einem Sonnendeck, ein Kreuzfahrtschiff vor einer sonnigen Mittelmeerküste und blühende Bougainvillea."><div class="campaign-brand">morgenwind<span>Die Welt wartet auf Sie.</span></div><div class="campaign-copy"><h2 id="campaign-title">Meer erleben.<br><em>Nichts bereuen.</em></h2><p>Traumurlaub mit<br>gutem Gewissen.</p></div><div class="campaign-seal"><span>Unser Versprechen</span><strong>Große Reise.<br>Gutes Gefühl.</strong><span>MS Morgenwind</span></div><div class="campaign-price"><span>7 Nächte ab</span><strong>800<span> €</span></strong><span>pro Person*</span></div><div class="campaign-destination">Mediterranean Escape <span>Sommer, der bleibt.</span></div></div><div class="campaign-promises"><p><strong>Jeden Morgen</strong>ein neuer Hafen.</p><p><strong>Komfort</strong>für alle.</p><p><strong>Moderne Technik.</strong>Ein gutes Gefühl.</p></div><div class="campaign-ticket"><div><span>Ihre Auszeit auf einen Blick</span><p><strong>7 Nächte</strong> auf See und an Land <b aria-hidden="true">·</b> <strong>4 Häfen</strong> voller Möglichkeiten</p></div><div class="campaign-ticket-end">Einsteigen.<br><strong>Alles andere vergessen.</strong></div></div><p class="campaign-fineprint">*Fiktives Angebot. Preis, Reisedauer, Route und Versprechen sind für den Unterricht erfunden. Das „gute Gefühl“ ist eine Werbeaussage, kein geprüftes Nachhaltigkeitssiegel.</p></section>`;}
function firstImpression(){return `<section class="intro-note campaign-response"><h2>Würdet ihr buchen?</h2><p>Was zieht euch an? Welche Aussage macht euch skeptisch? Tauscht euch zuerst ohne Recherche aus und nennt einen Beleg, den ihr von der Reederei verlangen würdet.</p>${note('start','Euer erster Eindruck: überzeugt, skeptisch oder unentschieden? Warum?')}</section>`;}
function advertising(){return campaign()+firstImpression()+`<div class="actions">${link('start','Zur Schiffsmission →')}${link('basis','Zum Nachhaltigkeitskompass',false)}</div>`;}
function storyMessage(id){const m=window.MISSION_STORY[id];return `<section class="brief story-message"><p class="meta">${esc(m.speaker)}</p><h2>${esc(m.title)}</h2>${m.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</section>`;}
function start(){return campaign()+`<div class="campaign-tools">${link('werbung','Werbung groß zeigen',false)}<span>Einstieg · Erst wirken lassen, dann hinterfragen.</span></div>`+firstImpression()+storyMessage('intro')+`<section class="voyage-hero"><div class="voyage-copy"><div class="kicker">MS Morgenwind · Der Nachhaltigkeitsfall</div><h1>Glänzende Decks.<br><em>Verborgene<br>Wahrheiten.</em></h1><p>Willkommen an Bord. Hinter der Fassade des Traumurlaubs warten drei verschlossene Akten auf euch.</p><div class="actions">${link('basis','Mission beginnen →')}${state.unlocked.length?link(D.find(s=>!state.unlocked.includes(s.id))?.id||'bruecke','Weiterarbeiten',false):''}</div><p class="meta">Wirtschaft & Recht 10 · 90 Minuten · 3–4 Personen</p></div><div class="ship-cutaway"><img src="assets/morgenwind.webp" width="1536" height="1024" fetchpriority="high" alt="Aufgeschnittenes Kreuzfahrtschiff bei Abendlicht: unten Maschinenraum und Crewkabinen, darüber Reedereibüro und Kommandobrücke.">${Object.entries(rooms).map(([id,r],i)=>`<a class="ship-pin pin-${id} ${state.unlocked.includes(id)?'complete':''}" href="#${id}" aria-label="${r.zone}: ${doorStatus(id)}"><span>${state.unlocked.includes(id)?'✓':i+1}</span><strong>${r.zone}</strong></a>`).join('')}<span class="image-caption">MS Morgenwind · Fiktive Schiffsansicht</span></div></section>${deckDoors()}<section class="intro-note"><div class="brief"><h3>Euer Auftrag</h3><p>Prüft im Auftrag der Kapitänin drei Bordakten. Löst die Aufgaben und Gegenproben, öffnet die Freigabevermerke und folgt den Nachrichten zur nächsten Station. Auf der Brücke erstellt ihr eure Empfehlung für die Pressekonferenz. Die 40 Minuten sind eine Richtzeit; es gibt keinen automatischen Abbruch.</p><p>Verteilt die Aufgaben: Eine Person liest, eine prüft Belege, eine führt das Logbuch. Bei vier Personen übernimmt eine die Zeit. Wechselt nach jeder Akte.</p></div></section>`;}
function basis(){const tasks=[['b1','Ein Unternehmen bleibt langfristig zahlungsfähig.','wirtschaft'],['b2','Die Belastung des Meeres sinkt.','umwelt'],['b3','Beschäftigte erhalten verlässlich freie Ruhezeiten.','soziales']];return head('Der Nachhaltigkeitskompass','Drei Fragen an eine Reise.','Nachhaltig handeln heißt: heute Bedürfnisse erfüllen, ohne die Lebensgrundlagen und Möglichkeiten künftiger Generationen zu gefährden.')+`<div class="compass-workspace">${compass()}<div class="dimensions"><div class="document-label">Bordbriefing · Euer Orientierungswissen</div><section class="dimension"><h3>Umwelt · Ökologie</h3><p>Werden Klima, Natur und Ressourcen geschützt? Beispiel: weniger Treibhausgase und Abfälle.</p></section><section class="dimension"><h3>Wirtschaft · Ökonomie</h3><p>Ist das Wirtschaften langfristig tragfähig? Beispiel: zahlungsfähig bleiben und in Verbesserungen investieren können.</p></section><section class="dimension"><h3>Soziales</h3><p>Können Menschen sicher, fair und mit verlässlichen Rechten leben und arbeiten? Beispiel: gute Bezahlung und Erholung.</p></section></div></div><div class="brief"><h3>Was ist ein Zielkonflikt?</h3><p>Höhere Löhne verbessern die Lage der Crew. Wenn die Preise gleich bleiben, kann zunächst der Gewinn sinken. Eine Maßnahme kann also ein Ziel fördern und ein anderes erschweren. Umgekehrt können sich Ziele unterstützen: Gesunde, zufriedene Beschäftigte können langfristig auch dem Betrieb helfen.</p></div><h2>Kompass einstellen</h2><p>Ordnet jedes Beispiel seiner hier vorrangigen Dimension zu. Besprecht mögliche Überschneidungen.</p><form id="basis-form">${tasks.map(([id,t])=>`<fieldset><legend>${t}</legend>${[['umwelt','Umwelt'],['wirtschaft','Wirtschaft'],['soziales','Soziales']].map(([v,l])=>`<label class="option"><input type="radio" name="${id}" value="${v}" ${state.basis[id]===v?'checked':''}><span>${l}</span></label>`).join('')}</fieldset>`).join('')}<button class="primary" type="submit">Zuordnung prüfen</button><p id="basis-feedback" class="feedback" role="status"></p></form><div class="actions">${link('umwelt','Zum Maschinenraum →')}</div>`;}
function numeric(value){const v=String(value??'').trim().replace(',','.');return /^\d+(\.\d+)?$/.test(v)?Number(v):NaN;}
function checkpointOK(s){return numeric(state.notes['calc-'+s.id])===Number(s.checkpoint.answer);}
function checkpoint(s){const c=s.checkpoint;return `<section class="brief"><h2>Gegenprobe · Selbst rechnen</h2><p>${c.task}</p><form id="calc-form" data-station="${s.id}"><label class="field"><span>Euer Ergebnis (${c.unit})</span><input type="text" inputmode="decimal" data-note="calc-${s.id}" value="${esc(state.notes['calc-'+s.id])}" maxlength="20" aria-describedby="calc-feedback"></label><button type="submit">Rechnung prüfen</button><p id="calc-feedback" class="feedback" role="status">${checkpointOK(s)?'✓ Gegenprobe stimmt.':''}</p></form><details><summary>Rechenhilfe 1</summary><p>${c.hint}</p></details><details><summary>Rechenhilfe 2</summary><p>${c.hint2}</p></details></section>`;}
function dossier(s){const d=s.dossier;return `<section class="stat-dossier"><h3>${d.title}</h3><p>${d.intro}</p>${d.bars?`<div class="stat-bars" aria-hidden="true"><p>Millionen Passagiere · Skala 0 bis 40</p>${d.bars.map(([y,v])=>`<div class="stat-row"><span>${y}</span><span class="stat-track"><span style="width:${v/40*100}%"></span></span><strong>${String(v).replace('.',',')}</strong></div>`).join('')}</div>`:''}<table><caption>${d.caption}</caption><thead><tr>${d.rows[0].map(v=>`<th scope="col">${v}</th>`).join('')}</tr></thead><tbody>${d.rows.slice(1).map(row=>`<tr>${row.map((v,i)=>i?`<td>${v}</td>`:`<th scope="row">${v}</th>`).join('')}</tr>`).join('')}</tbody></table><p class="source">${d.source}</p><h3>Die Zahlen einordnen</h3><p>${d.analysis}</p><p><strong>Statistikauftrag:</strong> ${d.task}</p>${note(s.id+'-stat','Eure Auswertung der Statistik')}</section>`;}
function station(s){const i=D.indexOf(s),locked=i>0&&!state.unlocked.includes(D[i-1].id);if(locked)return head('Noch gesperrt',s.title,'Öffnet zuerst die vorherige Bordakte. Diskussion, Quellen und Logbuch bleiben jederzeit erreichbar.')+`<div class="actions">${link(D[i-1].id,'Zur vorherigen Akte')}</div>`;const done=state.unlocked.includes(s.id);return head(`${s.dimension} · Bordakte ${i+1} · etwa ${s.time}`,s.lead,s.scene)+`<div class="investigation-workspace"><div class="material"><div class="document-masthead"><span>${icon("file")} MS Morgenwind · Bordarchiv</span><strong>Akte ${i+1} / ${s.dimension}</strong><small>Dokumente sichten · Belege sichern</small></div>${s.material}${dossier(s)}</div><div class="workbench"><div class="bench-label">${icon("compass")} Euer Ermittlungsauftrag</div><h2>Belege prüfen</h2><p>Wählt pro Aufgabe die belegbare Antwort. Die Zahl vor jeder richtigen Antwort ist eine Codeziffer. Lest die drei Ziffern in Aufgabenreihenfolge.</p><form id="station-form" data-station="${s.id}">${s.questions.map((q,n)=>`<fieldset><legend>${n+1}. ${q.title}</legend>${q.options.map(([v,l])=>`<label class="option"><input type="radio" name="q${n}" value="${v}" ${state.answers[s.id]?.[n]===v?'checked':''}><span><span class="digit">${v}</span>${l}</span></label>`).join('')}<p class="feedback" id="q-feedback-${n}"></p></fieldset>`).join('')}<button type="submit">Antworten prüfen</button><p id="station-feedback" class="feedback" role="status"></p></form>${checkpoint(s)}<h2>Haltet euren Befund fest</h2>${note(s.id,s.note)}<details><summary>Hilfestufe 1 · Den richtigen Ansatz finden</summary><p>${s.hints[0]}</p></details><details><summary>Hilfestufe 2 · Genauer hinschauen</summary><p>${s.hints[1]}</p></details><details><summary>Zusatzauftrag · Für euer Expertenteam</summary><p>${s.extra}</p>${note(s.id+'-extra','Eure weiterführende Überlegung (freiwillig)')}</details>${done?`<div class="unlocked"><h2>✓ Bordakte geöffnet</h2><p>${s.takeaway}</p><p class="meta">${esc(s.dispatch.speaker)}</p><h3>${esc(s.dispatch.title)}</h3><p>${esc(s.dispatch.text)}</p>${link(D[i+1]?.id||'bruecke',i===2?'Zur Brücke →':'Zur nächsten Bordakte →')}</div>`:`<div class="unlock"><div class="lock-emblem" aria-hidden="true">${icon("lock")}</div><h3>Öffnet die Bordakte</h3><p>Löst auch die Gegenprobe. Setzt dann die drei Ziffern eurer richtigen Antworten zusammen. Es gibt keine Zeitstrafe und keine begrenzte Zahl an Versuchen.</p><form id="code-form" data-station="${s.id}"><label class="field"><span>Dreistelliger Zugangscode</span><input class="code" type="text" name="code" inputmode="numeric" maxlength="3" autocomplete="off" aria-describedby="code-feedback"></label><button class="primary" type="submit">Akte öffnen</button><p id="code-feedback" class="feedback" role="status"></p></form></div>`}</div></div>`;}
const measures=[['land','Umwelt: Landstrom aus erneuerbaren Quellen nutzen, wo technisch möglich.'],['klima','Umwelt: Energieverbrauch und Treibhausgase der gesamten Reise messbar senken.'],['lohn','Soziales: Verlässliche Grundlöhne und überprüfbare Ruhezeiten vereinbaren.'],['rechte','Soziales: Eine unabhängige Beschwerdestelle für Beschäftigte einrichten.'],['invest','Wirtschaft: Verbesserungen mit einem langfristigen Kosten- und Investitionsplan finanzieren.'],['preis','Wirtschaft: Transparent kalkulierte Reisepreise statt dauerhaft nicht tragfähiger Angebote.']];
const costs={land:12000,klima:20000,lohn:14000,rechte:6000,invest:4000,preis:2000};
const euro=n=>n.toLocaleString('de-DE')+' €';
const packageCost=()=>measures.reduce((sum,[id])=>sum+(state.checks.includes(id)?costs[id]:0),0);
function budgetText(){const total=packageCost();return `Euer Paket: ${euro(total)}. ${total<=30000?'Noch verfügbar: '+euro(30000-total):'Budget überschritten um '+euro(total-30000)}. Gewinn bei 1.000 Gästen: ${euro(120000-total)}; bei 950 Gästen: ${euro(80000-total)}.`;}
function crisis(){return storyMessage('crisis')+`<section class="brief"><h2>Funkmeldung · 50 Buchungen fallen aus</h2><p><strong>Neue, fiktive Modellannahme:</strong> Nur noch 950 Gäste zahlen je 800 €. Die bisherigen Reisekosten bleiben bei 680.000 €. Euer gewähltes Maßnahmenpaket kommt dazu und <strong>ersetzt</strong> die pauschalen 30.000 € aus W1. Es wird nicht doppelt berechnet.</p><p>Die Geschäftsführung möchte mindestens 60.000 € Gewinn als Reserve behalten. Ist das mit eurem Paket noch möglich? Diese Reserve ist ein Wunsch der Geschäftsführung, keine allgemeine Nachhaltigkeitsregel.</p><form id="crisis-form"><label class="field"><span>Gewinn vor eurem Maßnahmenpaket, nach dem Buchungsrückgang (€; ohne Tausenderpunkte)</span><input inputmode="decimal" type="text" data-note="crisis-result" value="${esc(state.notes['crisis-result'])}" maxlength="20" aria-describedby="crisis-feedback"></label><button type="submit">Krisenrechnung prüfen</button><p id="crisis-feedback" class="feedback" role="status"></p></form><details><summary>Hilfe zur Funkmeldung</summary><p>Berechnet 950 × 800 € und zieht 680.000 € ab. Für euren endgültigen Gewinn zieht ihr danach die Kosten eures Pakets ab.</p></details>${note('krise','Eure Entscheidung: Paket ändern, geringere Reserve akzeptieren oder anders finanzieren? Nennt Folgen für zwei Dimensionen und nutzt einen Beleg aus einer Bordakte.')}</section>`;}
function bridge(){const complete=state.unlocked.length===3;return head('Die Pressekonferenz','Euer Bericht entscheidet.','Welche Empfehlung gebt ihr zur fiktiven MS Morgenwind? Ein Code öffnet Akten. Ein Urteil braucht Gründe.')+(!complete?`<div class="brief"><p><strong>${state.unlocked.length} von 3 Akten geöffnet.</strong> Für den vollständigen Bericht untersucht ihr alle drei. Bei Zeitende könnt ihr trotzdem hier und in der Diskussion weiterarbeiten. Kennzeichnet fehlende Belege ehrlich.</p></div>`:`<div class="brief"><p><strong>Alle drei Akten sind offen.</strong> Jetzt verbindet ihr eure Befunde. Für diese Entscheidung gibt es keinen vorgegebenen Meinungscode.</p></div>`)+storyMessage('bridge')+`<h2>Ein Maßnahmenpaket für die Reederei</h2><p>Ihr habt 30.000 € pro Reise. Wählt mindestens eine Maßnahme pro Dimension. Alle Beträge sind fiktive Zusatzkosten dieses Unterrichtsmodells, keine Marktpreise. Mehrere Lösungen sind möglich. Ein Paket über Budget braucht eine begründete zusätzliche Finanzierung. Prüft die Wirkungen mit U2, W3 und S3; ein günstiges Paket ist nicht automatisch das beste.</p>${measures.map(([id,t])=>`<label class="check-label"><input type="checkbox" data-measure="${id}" ${state.checks.includes(id)?'checked':''}><span>${t}<strong class="measure-cost">${euro(costs[id])} je Reise</strong></span></label>`).join('')}<p id="measure-feedback" class="feedback" role="status"></p><p id="budget-feedback" class="brief" role="status">${budgetText()}</p>${crisis()}${note('empfehlung','Eure Empfehlung: vertretbar, nur unter Bedingungen oder nicht vertretbar? Begründet mit zwei konkreten Belegen.','Wir empfehlen … Unser erster Beleg … Unser zweiter Beleg …')}${note('pruefung','Woran würdet ihr erkennen, ob die Maßnahmen tatsächlich umgesetzt werden?','Wir würden folgende Daten oder Kontrollen verlangen …')}${note('konflikt','Welcher Zielkonflikt bleibt? Wer profitiert und wer trägt Kosten?')}<div class="actions">${link('diskussion','In die Diskussion →')}${link('ergebnis','Logbuch ansehen',false)}</div>`;}
function discussion(){return head('Gemeinsam abwägen · 20 Minuten','Jetzt seid ihr gefragt.','Nutzt eure Belege, hört Gegenargumente an und trennt Tatsachen von Werturteilen.')+storyMessage('finale')+`<div class="brief"><p class="discussion-question">Unter welchen Bedingungen sind Kreuzfahrten vertretbar?</p><div class="positions"><span>Vertretbar</span><span>Nur unter Bedingungen</span><span>Nicht vertretbar</span></div><p>Stellt euch im Raum zu eurer Position oder meldet sie mündlich. Ihr dürft eure Position im Verlauf ändern.</p></div><h2>So läuft die Diskussion</h2><ol class="split-list"><li><strong>3 Minuten:</strong> Positioniert euch. Jedes Team nennt seine wichtigste Bedingung.</li><li><strong>8 Minuten:</strong> Prüft die Empfehlungen. Bezieht mindestens einen Umwelt-, Wirtschafts- und Sozialaspekt ein.</li><li><strong>6 Minuten:</strong> Wer sollte handeln: Reedereien, Reisende oder Politik? Diskutiert Kosten, Verantwortung und wirksame Kontrollen.</li><li><strong>3 Minuten:</strong> Positioniert euch erneut. Welcher Beleg hat euer Urteil verändert oder bestärkt?</li></ol><h2>Fragen, die weiterführen</h2><ul class="split-list"><li>Reicht „besser als vorher“ schon für „nachhaltig“?</li><li>Wer bezahlt höhere Löhne und sauberere Technik? Welche Interessen stehen sich gegenüber?</li><li>Welche Informationen fehlen für ein endgültiges Urteil?</li><li>Welche Alternative zur Kreuzfahrt wäre für euch vorstellbar? Nach welchen Kriterien würdet ihr vergleichen?</li></ul><div class="brief"><h3>Falls eure Akten noch nicht vollständig sind</h3><p>Prüft diese drei Ausgangspunkte im Plenum: Landstrom wirkt vor allem im Hafen. Ein Unternehmen braucht langfristig tragfähige Einnahmen und Kosten. Gute Arbeitsbedingungen umfassen Geld, Erholung und Rechte. Ergänzt Belege aus den Teams, die die jeweilige Akte untersucht haben.</p></div>${note('diskussion','Ein starkes Gegenargument und eure Antwort darauf')}${storyMessage('ending')}<h2>Exit-Ticket · Jede Person für sich</h2><p>Schreibt zum Schluss auf einen eigenen Zettel: <strong>mein Urteil, zwei Belege, ein verbleibender Zielkonflikt.</strong> Ergänzt: „Meine erste Einschätzung hat sich …, weil …“. Das Teamgerät ersetzt nicht euer persönliches Urteil.</p><div class="actions">${link('ergebnis','Team-Logbuch ansehen →')}</div>`;}
function sources(){return head('Quellen und Einordnung','Was ist belegt? Was ist erfunden?','Alle Spieltexte sind eigenständig formuliert. Die MS Morgenwind, alle handelnden Personen, ihre Nachrichten, die Werbung und die Kalkulation sind fiktiv.')+`<ol class="source-list"><li><strong>Grundlage: Joachim Herz Stiftung</strong><p>Johannes Heuser: „Traum oder Albtraum: Kreuzfahrten im Nachhaltigkeits-Check“, Produktion C. C. Buchner Verlag. Von der Lehrkraft bereitgestelltes PDF, 16 Seiten. M1: Nachhaltigkeitsdimensionen; M2/M3: Umwelt; M4–M7: Wirtschaft; M8/M9: Arbeit. Die Quellen und Zahlen stammen überwiegend aus 2016–2019.</p></li><li><a href="https://www.imo.org/en/mediacentre/pages/whatsnew-2254.aspx" target="_blank" rel="noopener">IMO: New sulphur emission limits enter into effect in the Mediterranean</a><p>01.05.2025. Grundlage für Beleg U3: Schwefel-Emissionskontrollgebiet Mittelmeer und Grenzwerte.</p></li><li><a href="https://www.umweltbundesamt.de/themen/verkehr/emissionsstandards/seeverkehr-luftschadstoffe-treibhausgase" target="_blank" rel="noopener">Umweltbundesamt: Seeverkehr – Luftschadstoffe, Treibhausgase und Energieeffizienz</a><p>Aktualisiert am 05.08.2025. Grundlage für U1/U2: Luftschadstoffe, Klimawirkung, LNG/Methanschlupf und Landstrom.</p></li><li><strong>CLIA · Branchenstatistik</strong><p><a href="https://cruising.org/about-cruise-markets" target="_blank" rel="noopener">About Cruise Markets: Passagieraufkommen 2023/2024</a>; <a href="https://www.cruising.org/news/cruise-industry-sees-strong-demand-global-impact-expands-and-investments-efficiency-and-future" target="_blank" rel="noopener">State of the Cruise Industry, 15.04.2026: Passagieraufkommen 2025</a>. Gerundete Werte. CLIA vertritt die Kreuzfahrtbranche; ihre Passagierstatistik ist kein unabhängiger Nachweis für Nachhaltigkeit. Abgerufen am 15.10.2026.</p></li><li><strong>Historische Lohntabelle</strong><p>M9 auf Seite 14 des bereitgestellten PDFs; dort nach Claus Hecking: „Mein Schiff 6“ von TUI Cruises, Leinen los, Steuern umschiffen!, Spiegel Online, 01.06.2017. Lohnstand 2016, Gesamtgehälter inklusive Zuschlägen. Kein Vergleich mit heutigen Löhnen und keine Aussage über alle Beschäftigten.</p></li><li><strong>Eigene Unterrichtsmodelle</strong><p>Die Reiseabrechnung W1/W2, die Vertragsangebote S3, die Maßnahmenkosten und die Funkmeldung auf der Brücke sowie die Werbeaussagen sind erfunden. Sie dienen der Analyse und sind keine realen Unternehmensangaben.</p></li></ol><p class="meta">Recherche und Prüfung: 15.10.2026. Die historischen Aussagen aus dem Originalmaterial wurden nicht ungeprüft als Gegenwartsbeschreibung übernommen. Das Original-PDF wird hier nicht veröffentlicht.</p>`;}
function report(){const labels=[['start','Erste Einschätzung'],...D.flatMap(s=>[[s.id,s.title+' · Befund'],[s.id+'-extra',s.title+' · Zusatzauftrag'],[s.id+'-stat',s.title+' · Statistikauswertung']]),...D.map(s=>['calc-'+s.id,s.title+' · Gegenprobe ('+s.checkpoint.unit+')']),['crisis-result','Krisenrechnung · Gewinn vor Maßnahmen (€)'],['krise','Unsere Entscheidung nach der Funkmeldung'],['empfehlung','Unsere Empfehlung und Belege'],['pruefung','Kontrolle der Maßnahmen'],['konflikt','Verbleibender Zielkonflikt'],['diskussion','Gegenargument und Antwort']];return head('Ergebnisübersicht','Euer Team-Logbuch',`${state.unlocked.length} von 3 Akten geöffnet. Die Übersicht enthält eure eigenen Überlegungen, keine automatische Bewertung.`)+`<div class="actions"><button class="primary" id="print">Logbuch drucken / als PDF sichern</button>${link('bruecke','Bericht bearbeiten',false)}</div>${D.map(s=>`<section class="report-block"><h2>${s.title}</h2><p>${state.unlocked.includes(s.id)?'✓ Akte geöffnet':'Noch nicht geöffnet'}</p><p>${state.unlocked.includes(s.id)?s.takeaway:'Befunde im Team ergänzen.'}</p></section>`).join('')}<section class="report-block"><h2>Ausgewählte Maßnahmen</h2><p>${budgetText()}</p>${state.checks.length?`<ul>${measures.filter(([id])=>state.checks.includes(id)).map(([,t])=>`<li>${t}</li>`).join('')}</ul>`:'<p class="empty">Noch keine Maßnahmen ausgewählt.</p>'}</section>${labels.map(([id,l])=>`<section class="report-block"><h2>${l}</h2><p class="${state.notes[id]?'':'empty'}">${esc(state.notes[id]||'Noch kein Eintrag.')}</p></section>`).join('')}<p class="meta">Mission Traumschiff · Wirtschaft & Recht 10 · Quellenstand 15.10.2026 · daniel-zahnweh.de/10/Kreuzfahrt/</p>`;}
function measureFeedback(){const budget=document.querySelector('#budget-feedback');if(budget)budget.textContent=budgetText();const el=document.querySelector('#measure-feedback');if(el){const groups=[['land','klima'],['lohn','rechte'],['invest','preis']];const missing=groups.map((g,i)=>g.some(x=>state.checks.includes(x))?null:['Umwelt','Soziales','Wirtschaft'][i]).filter(Boolean);el.textContent=missing.length?'Für euer Paket fehlt noch eine Maßnahme zu: '+missing.join(', ')+'.':'Alle drei Dimensionen sind vertreten. Begründet jetzt eure Auswahl.';}}
function render(focus=true){const id=route();document.body.dataset.view=id;state.route=id;save();nav();const f={start,werbung:advertising,basis,bruecke:bridge,diskussion:discussion,quellen:sources,ergebnis:report};main.innerHTML=f[id]?f[id]():station(D.find(s=>s.id===id));document.title=(D.find(s=>s.id===id)?.title||({start:'An Bord',werbung:'Die Kreuzfahrtwerbung',basis:'Nachhaltigkeitskompass',bruecke:'Euer Bericht',diskussion:'Diskussion',quellen:'Quellen',ergebnis:'Logbuch'}[id]))+' · Mission Traumschiff';measureFeedback();if(focus){main.focus({preventScroll:true});window.scrollTo(0,0);}}
main.addEventListener('input',e=>{if(e.target.dataset.note){state.notes[e.target.dataset.note]=e.target.value;save();}});
main.addEventListener('change',e=>{const el=e.target;if(el.closest('#station-form')){const id=el.closest('form').dataset.station;state.answers[id]??={};state.answers[id][Number(el.name.slice(1))]=el.value;}if(el.closest('#basis-form'))state.basis[el.name]=el.value;if(el.dataset.measure){state.checks=state.checks.filter(x=>x!==el.dataset.measure);if(el.checked)state.checks.push(el.dataset.measure);measureFeedback();}save();});
function feedback(el,text,ok){el.textContent=text;el.className='feedback '+(ok?'success':'error');}
main.addEventListener('submit',e=>{e.preventDefault();const form=e.target;
 if(form.id==='crisis-form'){const ok=numeric(state.notes['crisis-result'])===80000;feedback(document.querySelector('#crisis-feedback'),ok?'✓ Vor eurem Paket bleiben 80.000 €. Vergleicht nun euren Restgewinn mit der gewünschten Reserve.':'Prüft zuerst 950 × 800 €. Zieht danach die bisherigen Kosten ab; noch nicht euer Paket.',ok);}
 if(form.id==='calc-form'){const s=D.find(x=>x.id===form.dataset.station);feedback(document.querySelector('#calc-feedback'),checkpointOK(s)?'✓ Gegenprobe stimmt. Erklärt euch gegenseitig den Rechenweg.':'Das Ergebnis passt noch nicht. '+s.checkpoint.hint,checkpointOK(s));}
 if(form.id==='basis-form'){const correct=state.basis.b1==='wirtschaft'&&state.basis.b2==='umwelt'&&state.basis.b3==='soziales';feedback(document.querySelector('#basis-feedback'),correct?'✓ Euer Kompass stimmt. Zahlungsfähigkeit: Wirtschaft. Meeresschutz: Umwelt. Ruhezeiten: Soziales.':'Prüft die Leitfragen oben: Geht es vorrangig um den Betrieb, die Natur oder die Beschäftigten? Ordnet alle drei Beispiele zu.',correct);}
 if(form.id==='station-form'){const s=D.find(x=>x.id===form.dataset.station);let n=0;s.questions.forEach((q,i)=>{const ok=state.answers[s.id]?.[i]===q.answer;if(ok)n++;feedback(document.querySelector('#q-feedback-'+i),ok?'✓ Durch das Material belegt.':(state.answers[s.id]?.[i]?q.feedback:'Wählt zuerst eine Antwort.'),ok);});feedback(document.querySelector('#station-feedback'),n===3?'✓ Alle Antworten sind belegt. Notiert euren Befund und setzt die drei Codeziffern zusammen.':`${n} von 3 Antworten passen. Lest die Hinweise bei den Aufgaben und versucht es erneut.`,n===3);}
 if(form.id==='code-form'){const s=D.find(x=>x.id===form.dataset.station),code=new FormData(form).get('code').trim();const correctAnswers=s.questions.every((q,i)=>state.answers[s.id]?.[i]===q.answer);if(code===s.code&&correctAnswers&&checkpointOK(s)){if(!state.unlocked.includes(s.id))state.unlocked.push(s.id);save();render(false);document.querySelector('.unlocked').scrollIntoView({block:'center'});document.querySelector('.unlocked a').focus({preventScroll:true});document.querySelector('#announcement').textContent='Bordakte geöffnet. '+s.takeaway;}else feedback(document.querySelector('#code-feedback'),!correctAnswers?'Prüft zuerst eure drei Antworten. Der Code muss sich aus fachlich richtigen Antworten ergeben.':!checkpointOK(s)?'Löst zuerst die Gegenprobe. Nutzt bei Bedarf die beiden Rechenhilfen.':'Der Code passt noch nicht. Übernehmt die Ziffern der richtigen Antworten in der Reihenfolge 1, 2, 3.',false);}
});
main.addEventListener('click',e=>{if(e.target.closest('#print'))window.print();});
const dialog=document.querySelector('#reset-dialog');document.querySelector('#reset').addEventListener('click',()=>dialog.showModal());document.querySelector('#cancel-reset').addEventListener('click',()=>dialog.close());document.querySelector('#confirm-reset').addEventListener('click',()=>{state=fresh();save();dialog.close();if(location.hash==='#start')render();else location.hash='start';});
document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();});
window.addEventListener('hashchange',()=>render());render(false);
})();
